const item = (options: {
  name: string;
  label: string;
  module: string;
  rung: number;
  positive: string;
  negative: string;
  construct: string;
  design?: string;
  game?: string;
}): SurveyItem => {
  const situation = CRISIS_SITUATED_MODULES[options.module]?.situation;
  return {
    name: options.name,
    label: options.label,
    wording: situation
      ? `${situation}\n\n${CRISIS_SITUATED_STEM}`
      : CRISIS_SITUATED_STEM,
    tag: "attitude",
    topic: options.module,
    options: [
      { code: 1, label: options.positive },
      { code: 2, label: options.negative },
    ],
    range: [1, 2],
    coverage: 1,
    meta: {
      construct: options.construct,
      module: options.module,
      rung: options.rung,
      ...(options.design ? { design: options.design } : {}),
      ...(options.game ? { game: options.game } : {}),
    },
  };
};

